		return LaunchProfile{}, err
	}
	review := cfg.TrailsReviewEnabled && cfg.Output.isCodeReview()
	if triggerType == "push" {
		firstClass := cfg.writesTrailBody() || cfg.writesTrailMonitor()
		if !review && (!firstClass || cfg.TrailsReviewEnabled) {
			return LaunchProfile{}, errors.New("push runner config must be either a review or first-class trail-output runner")
		}
	}
	p := profileFromConfig(cfg, review)
	values := map[string]string{}
	if triggerType == "checks_failed" {
		values["target"], values["failing_checks"] = "commit", "checks"
	}
	if _, err := p.RenderPrompt("branch", "base", "[]", values); err != nil {
		return LaunchProfile{}, err
	}
	return p, nil
}

// writesTrailBody and writesTrailMonitor report the trail-scoped effects this
// run can actually have. A declaration the adapter cannot carry is not one —
// the runtime skips it — so counting declarations would keep relaunching a
// runner that produces nothing.
func (c LaunchConfig) writesTrailBody() bool {
	return c.Output.TrailField == "body" && TrailFieldCapableAdapter(c.Output.Adapter)
}

func (c LaunchConfig) writesTrailMonitor() bool {
	return c.Output.TrailMonitor != nil && MonitorCapableAdapter(c.Output.Adapter)
}

func (p OutputProfile) isCodeReview() bool {
	return p.Adapter == "last_json_line" && strings.TrimSpace(p.ResultType) == codeReviewCommentsResultType
}

func profileFromConfig(cfg LaunchConfig, review bool) LaunchProfile {
	// Mirrors handlers.go's review-publish trigger, which keys on the output
	// shape alone. Gating this on `review` instead would let a runner with no
	// trails_review block be treated as body-only while it still publishes.
	bodyIsSoleOutput := !cfg.Output.isCodeReview() && cfg.writesTrailBody() && !cfg.writesTrailMonitor()
	return LaunchProfile{Agent: cfg.Agent, TimeoutMS: cfg.TimeoutMS, Model: cfg.Model, ExtraArgs: cfg.ExtraArgs, AutoStopMinutes: cfg.AutoStopMinutes, PromptTemplate: cfg.PromptTemplate, Output: cfg.Output.Raw, IncludePreviousFindings: review, BodyIsSoleOutput: bodyIsSoleOutput}
}
func ParsePushLaunchConfig(raw, id string) (LaunchProfile, error) {
	return ParseLaunchConfig(raw, id, "push")
}
func ParseLaunchConfig(raw, id, trigger string) (LaunchProfile, error) {
	cfg, err := ParseLaunchConfigDocument(raw, id)
	if err != nil {
		return LaunchProfile{}, err
	}
	return SelectEventLaunch(cfg, trigger)
}

